Input: {"question": "What is the historical period associated with the John Mason House?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 0, "end": 156, "text": "John Mason House (Lexington, Massachusetts) The John Mason House is an historic First Period house on 1303 Massachusetts Avenue in Lexington, Massachusetts."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 157, "end": 316, "text": "It is a 2-1/2 story wood frame structure, its main block three bays wide, with a side gable roof, clapboard siding, and two chimneys set behind the roof ridge."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 317, "end": 406, "text": "A leanto section to the rear gives it a saltbox profile, and an ell extends to the right."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 407, "end": 500, "text": "The oldest portion of the house, a three-bay portion of its main block, was built circa 1715."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 501, "end": 570, "text": "The building has been repeatedly extended and altered over the years."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0497-da80b4c9eb42:d00", "start": 571, "end": 586, "text": "John Mason, its"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 0, "end": 53, "text": "and 1871 this house was purchased by George Thurlow ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 54, "end": 132, "text": "This property remained in the Thurlow family until the mid-twentieth century ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 133, "end": 177, "text": "NWB.571 Benjamin Coker House , 172 State St."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 178, "end": 361, "text": "Newburyport MA c 1700 The Benjamin Coker House embodies in its roof frame and second story tie beam , clear evidence of a distinctive First Period plan type and construction methods ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 362, "end": 449, "text": "While the house is undocumented before 1719 , the style and construction suggest a ca ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 450, "end": 461, "text": "1700 date ."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0497-da80b4c9eb42:d01", "start": 462, "end": 552, "text": "The house began as a single cell , two story house , located at High and Federal Streets ."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0497-da80b4c9eb42:d02", "start": 0, "end": 120, "text": "John Chipman , who built the present house to accommodate his parish duties and his growing family of fifteen children ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0497-da80b4c9eb42:d02", "start": 121, "end": 448, "text": "The Exercise Conant House is the First Period , northern ell of the two-and-a-half story , five-bay Georgian house built by the Reverend John Chipman House , which has a dentilled cornice and an original fine Second-Period , central doorway with fluted pilasters and a broken-arch pediment with pineapple finial in the center ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0497-da80b4c9eb42:d02", "start": 449, "end": 599, "text": "The First Period Conant ell is a single-cell , two-and-a-half story structure , three bays wide , possibly originally oriented north , with chimney to"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0497-da80b4c9eb42:d03", "start": 0, "end": 137, "text": "John Mason House (Winchester, Massachusetts) The John Mason House is a historic house at 10 Hillside Avenue in Winchester, Massachusetts."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0497-da80b4c9eb42:d03", "start": 138, "end": 277, "text": "This two story wood frame house was built sometime in the 1860s, probably for Joshua Stone, who sold it to John Mason sometime before 1875."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0497-da80b4c9eb42:d03", "start": 278, "end": 372, "text": "Mason was one of the first Boston businessmen to establish a suburban residence in Winchester."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0497-da80b4c9eb42:d03", "start": 373, "end": 597, "text": "The house has a variety of high-style Italianate features, including a characteristic low-pitch hip roof with decorative brackets, and a three-bay front facade in which paired narrow windows are topped by decorative framing."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0497-da80b4c9eb42:d03", "start": 598, "end": 631, "text": "The front entry is sheltered by a"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 0, "end": 7, "text": "John W."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 8, "end": 31, "text": "Mason House The John W."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 32, "end": 117, "text": "Mason House is a historic building located in Fergus Falls, Minnesota, United States."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 118, "end": 195, "text": "Mason was a native of Lapeer, Michigan and one of the first settlers in town."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 196, "end": 243, "text": "He arrived in 1871 to establish a law practice."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 244, "end": 362, "text": "He served in the Minnesota Legislature, he was the first mayor of Fergus Falls, and later served as its city attorney."}, "D5S7": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 363, "end": 454, "text": "Mason built a small home on this same lot in 1875, and replaced it with this house in 1881."}, "D5S8": {"document_number": 5, "doc_id": "ramdocs-0497-da80b4c9eb42:d04", "start": 455, "end": 551, "text": "It is a two-story wood frame structure that features a limestone foundation, low pitch hip roof,"}}, "original_cards": [{"doc_id": "ramdocs-0497-da80b4c9eb42:d00", "card_id": "ramdocs-0497-da80b4c9eb42:d00:c0", "entity": "John Mason House", "scope": "historical period", "claim": "The John Mason House is associated with the First Period.", "answer": "First Period", "quote": "John Mason House (Lexington, Massachusetts) The John Mason House is an historic First Period house on 1303 Massachusetts Avenue in Lexington, Massachusetts.", "original_document_number": 1}, {"doc_id": "ramdocs-0497-da80b4c9eb42:d03", "card_id": "ramdocs-0497-da80b4c9eb42:d03:c0", "entity": "John Mason House", "scope": "historical period", "claim": "The historical period associated with the John Mason House is the 1860s.", "answer": "1860s", "quote": "This two story wood frame house was built sometime in the 1860s, probably for Joshua Stone, who sold it to John Mason sometime before 1875.", "original_document_number": 4}], "current_answers": ["First Period", "1860s", "circa 1715"], "candidate_answers": [{"candidate_id": "R0", "answer": "First Period", "origin": "initial"}, {"candidate_id": "R1", "answer": "1860s", "origin": "initial"}, {"candidate_id": "R2", "answer": "circa 1715", "origin": "coverage_addition"}]}
